import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # ---- De-duplicate CDC events: "distinct by seq" (at-least-once delivery) ----
    if not cdc_events.empty:
        cdc_events = cdc_events.reset_index(drop=False).rename(columns={"index": "_orig_idx"})
        cdc_events = cdc_events.sort_values(["seq", "_orig_idx"], kind="mergesort")
        cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")
    else:
        cdc_events["_orig_idx"] = pd.Series(dtype="int64")

    # ---- Build target lookup: one row per order_id.
    # Defensive deterministic tie-break in case of duplicate keys: highest
    # last_seq wins (most recent watermark); ties broken by original row order.
    target_dict = {}
    if not target_state.empty:
        ts = target_state.reset_index(drop=False).rename(columns={"index": "_orig_idx"})
        ts = ts.sort_values(
            ["order_id", "last_seq", "_orig_idx"],
            ascending=[True, False, True],
            kind="mergesort",
        )
        ts = ts.drop_duplicates(subset=["order_id"], keep="first")
        for r in ts.itertuples(index=False):
            target_dict[int(r.order_id)] = {
                "status": r.status,
                "amount": r.amount,
                "last_seq": int(r.last_seq),
            }

    # ---- Group remaining (deduped) CDC events per order, in seq order ----
    events_by_order = {}
    if not cdc_events.empty:
        for oid, grp in cdc_events.groupby("order_id", sort=False):
            events_by_order[int(oid)] = grp.sort_values(["seq"], kind="mergesort")

    all_order_ids = sorted(set(target_dict.keys()) | set(events_by_order.keys()))

    new_state_rows = []
    tombstone_rows = []

    for oid in all_order_ids:
        if oid in target_dict:
            status = target_dict[oid]["status"]
            amount = target_dict[oid]["amount"]
            last_seq = target_dict[oid]["last_seq"]
            has_row = True
            had_row_ever = True
            guard_seq = last_seq
        else:
            status = None
            amount = None
            last_seq = None
            has_row = False
            had_row_ever = False
            guard_seq = None

        last_applied_op = None
        last_applied_seq = None

        events = events_by_order.get(oid)
        if events is not None:
            for ev in events.itertuples(index=False):
                seq = int(ev.seq)

                # Replay guard: skip events already reflected in target_state.
                if guard_seq is not None and seq <= guard_seq:
                    continue

                op = ev.op
                ev_status = ev.status
                ev_amount = ev.amount

                if op in ("I", "U"):
                    if has_row:
                        if op == "U" and pd.isna(ev_amount):
                            # NULL amount on update leaves existing amount unchanged.
                            pass
                        else:
                            amount = ev_amount
                        status = ev_status
                    else:
                        # Create the row from scratch; amount taken as-is (NULL stays NULL).
                        status = ev_status
                        amount = ev_amount
                        has_row = True
                        had_row_ever = True
                    last_seq = seq
                elif op == "D":
                    has_row = False
                    # amount/status become irrelevant; a later I/U recreates from scratch.

                last_applied_op = op
                last_applied_seq = seq

        if has_row:
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": status,
                    "amount": amount,
                    "last_seq": last_seq,
                }
            )

        if had_row_ever and last_applied_op == "D":
            tombstone_rows.append(
                {
                    "order_id": oid,
                    "deleted_seq": last_applied_seq,
                }
            )

    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    tombstones = pd.DataFrame(
        tombstone_rows, columns=["order_id", "deleted_seq"]
    )

    if not new_state.empty:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["status"] = new_state["status"].astype("object")
        new_state = new_state.sort_values("order_id", kind="mergesort").reset_index(drop=True)
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype="object"),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    if not tombstones.empty:
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
        tombstones = tombstones.sort_values("order_id", kind="mergesort").reset_index(drop=True)
    else:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones}
